import { NavLink, Link } from "react-router-dom";
import { useState } from "react";
import { Menu, X } from "lucide-react";
import { SHOP } from "@/lib/shopInfo";

const links = [
  { to: "/", label: "Home", testId: "nav-home" },
  { to: "/products", label: "Our Sweets", testId: "nav-products" },
  { to: "/about", label: "Heritage", testId: "nav-about" },
  { to: "/contact", label: "Contact", testId: "nav-contact" },
];

export default function Navbar() {
  const [open, setOpen] = useState(false);

  return (
    <header
      className="sticky top-0 z-40 backdrop-blur-xl bg-brand-ivory/85 border-b border-brand-border"
      data-testid="site-navbar"
    >
      <div className="mx-auto max-w-7xl px-6 lg:px-10 h-20 flex items-center justify-between">
        <Link to="/" className="flex items-center gap-3 group">
          <span className="h-11 w-11 rounded-full border border-brand-gold/70 flex items-center justify-center font-serif text-brand-maroon text-xl tracking-tight group-hover:bg-brand-maroon group-hover:text-brand-ivory transition-colors">
            N
          </span>
          <span className="flex flex-col leading-tight">
            <span className="font-serif text-brand-maroon text-lg sm:text-xl tracking-wide">
              {SHOP.name}
            </span>
            <span className="text-[10px] tracking-[0.3em] uppercase text-brand-gold">
              {SHOP.since}
            </span>
          </span>
        </Link>

        <nav className="hidden md:flex items-center gap-9">
          {links.map((l) => (
            <NavLink
              key={l.to}
              to={l.to}
              end={l.to === "/"}
              data-testid={l.testId}
              className={({ isActive }) =>
                `text-sm tracking-[0.18em] uppercase font-medium transition-colors ${
                  isActive
                    ? "text-brand-maroon"
                    : "text-brand-text/70 hover:text-brand-maroon"
                }`
              }
            >
              {l.label}
            </NavLink>
          ))}
        </nav>

        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          className="md:hidden inline-flex items-center justify-center h-10 w-10 text-brand-maroon"
          aria-label="Toggle menu"
        >
          {open ? <X size={22} /> : <Menu size={22} />}
        </button>
      </div>

      {open && (
        <div className="md:hidden border-t border-brand-border bg-brand-ivory">
          <div className="mx-auto max-w-7xl px-6 py-4 flex flex-col gap-3">
            {links.map((l) => (
              <NavLink
                key={l.to}
                to={l.to}
                end={l.to === "/"}
                onClick={() => setOpen(false)}
                data-testid={`${l.testId}-mobile`}
                className={({ isActive }) =>
                  `py-2 text-sm tracking-[0.18em] uppercase font-medium ${
                    isActive ? "text-brand-maroon" : "text-brand-text/70"
                  }`
                }
              >
                {l.label}
              </NavLink>
            ))}
          </div>
        </div>
      )}
    </header>
  );
}
